"""Static data: version, embedded app icon and the page-extraction script."""

VERSION = "2.0"

ICON_B64 = """"""

# JavaScript injected into the loaded forum page to extract mod info.
# NodeBB's first post holds the description; og:* meta tags give the title
# and primary image. Images are filtered to user uploads only (real
# screenshots), excluding avatars, emojis and forum system graphics.
EXTRACT_JS = r"""
(function () {
    function meta(prop) {
        var el = document.querySelector('meta[property="' + prop + '"]')
              || document.querySelector('meta[name="' + prop + '"]');
        return el ? (el.getAttribute('content') || '').trim() : '';
    }
    function abs(u) {
        try { return new URL(u, document.baseURI).href; } catch (e) { return u; }
    }
    function keepImg(u) {
        if (!u) return false;
        var low = u.toLowerCase();
        if (low.indexOf('/assets/uploads/files/') !== -1) return true;
        if (low.indexOf('/assets/uploads/') !== -1 &&
            low.indexOf('profile') === -1) return true;
        return false;
    }

    var title = meta('og:title') || (document.querySelector('h1')
                && document.querySelector('h1').innerText.trim())
              || document.title || '';

    // Description: prefer the first post's rendered text, fall back to og.
    var desc = '';
    var firstPost = document.querySelector('[component="post"]')
                 || document.querySelector('.post-content')
                 || document.querySelector('.postbody');
    if (firstPost) {
        var clone = firstPost.cloneNode(true);
        // Drop NodeBB signatures / credits / post tools from the text.
        clone.querySelectorAll('.post-signature, .post-tools, .post-info, '
                             + '.registered-user, blockquote, .ipsType_light')
             .forEach(function (n) { n.remove(); });
        desc = (clone.innerText || '').trim();
    }
    if (!desc) desc = meta('og:description');

    // Collect images: og:image first, then all <img> in first post.
    var imgs = [];
    var og = meta('og:image');
    if (og) imgs.push(abs(og));
    var scope = firstPost || document;
    scope.querySelectorAll('img').forEach(function (im) {
        var src = im.getAttribute('src') || im.getAttribute('data-src') || '';
        if (src) imgs.push(abs(src));
    });

    var seen = {}, filtered = [];
    imgs.forEach(function (u) {
        if (!seen[u] && keepImg(u)) { seen[u] = 1; filtered.push(u); }
    });

    // "ready" = the content we care about is actually in the DOM. NodeBB
    // server-renders the first post, so this flips true well before the page
    // finishes loading all its images/scripts (document.readyState "complete").
    var ready = !!(firstPost || meta('og:description'));

    return JSON.stringify({
        title: title,
        description: desc,
        images: filtered,
        ready: ready,
        pageOk: document.title.indexOf('Just a moment') === -1
    });
})();
"""
